"""usage: mv.py SRC DST MODDOC NAME... ; moves top-level items NAME (with leading doc/attrs) from SRC to new/appended DST."""
import re, sys, os
src, dst, moddoc, *names = sys.argv[1:]
L = open(src).read().split('\n')
item = re.compile(r'^(pub(\([a-z]+\))? )?(async )?(fn|const|static|enum|struct|impl|type|trait|mod|use)\b')
def name_of(line):
    m = re.match(r'^(?:pub(?:\([a-z]+\))? )?(?:fn|const|static|enum|struct|type|trait)\s+([A-Za-z_0-9]+)', line)
    if m: return m.group(1)
    m = re.match(r'^impl(?:<[^>]*>)?\s+(.*?)\s*\{?$', line)
    return 'impl ' + m.group(1) if m else None
# block starts
starts = []
for i, l in enumerate(L):
    if item.match(l):
        j = i
        while j > 0 and (L[j-1].startswith('///') or L[j-1].startswith('#[')):
            j -= 1
        starts.append((j, i))
blocks = {}
for k, (j, i) in enumerate(starts):
    # end: scan from item line to its closing at col 0
    if L[i].rstrip().endswith(';') or re.match(r'.*;\s*$', L[i]) and '{' not in L[i]:
        e = i
    else:
        e = i
        # find terminator: line that is '}' or ends with ';' at col 0 after item line
        while e < len(L):
            if e > i and (L[e].startswith('}') or (re.match(r'^\S', L[e]) is None and False)):
                break
            if e >= i and L[e].rstrip().endswith(';') and not L[e].startswith(' ') and e == i:
                break
            e += 1
            if e < len(L) and re.match(r'^\S.*;\s*$', L[e]) and not L[e].startswith('}') and not item.match(L[e]) is None and False:
                break
        # multi-line const/static: ends at first line ending with ';' at depth 0
        if re.match(r'^(pub(\([a-z]+\))? )?(const|static|type|use)\b', L[i]):
            e = i
            while not L[e].rstrip().endswith(';'):
                e += 1
    nm = name_of(L[i])
    if nm: blocks.setdefault(nm, []).append((j, e))
sel = []
for n in names:
    assert n in blocks, f'{n} not found'
    assert len(blocks[n]) == 1, f'{n} ambiguous'
    sel.append(blocks[n][0])
out = []
for j, e in sel:
    out += L[j:e+1] + ['']
drop = set()
for j, e in sel:
    drop |= set(range(j, e + 1))
    if e + 1 < len(L) and L[e+1] == '': drop.add(e + 1)
new = [l for i, l in enumerate(L) if i not in drop]
open(src, 'w').write('\n'.join(new))
body = '\n'.join(out).rstrip('\n') + '\n'
if os.path.exists(dst):
    open(dst, 'a').write('\n' + body)
else:
    hdr = '// SPDX-License-Identifier: CC0-1.0\n\n' + '\n'.join('//! ' + x if x else '//!' for x in moddoc.split('\\n')) + '\n\nuse super::*;\n\n'
    open(dst, 'w').write(hdr + body)
print('moved', len(sel), 'items,', len(drop), 'lines')
EOF
