impl<Eng: ::std::marker::Send + ::std::marker::Sync + 'static> smithy_server_runtime::Operation
    for SendMessage<Eng>
{
    type Input = SendMessageInput;
    type Output = SendMessageOutput;
    type Error = SendMessageError;

    const NAME: &'static str = "SendMessage";
    const INPUT_SCHEMA: &'static ::aws_smithy_schema::Schema = super::types::SEND_MESSAGE_INPUT_SCHEMA;
    const OUTPUT_SCHEMA: &'static ::aws_smithy_schema::Schema = super::types::SEND_MESSAGE_OUTPUT_SCHEMA;
    const SUCCESS_STATUS: u16 = 200u16;

    async fn handle(
        &self,
        input: Self::Input,
        ctx: &smithy_server_runtime::OperationContext<'_>,
    ) -> Result<Self::Output, Self::Error> {
        // "The message to send. The minimum size is one character": a `MessageBody`
        // holding no character is the required parameter not supplied, which is what
        // `MissingParameter` reports. Refused before the store is touched, so nothing is
        // enqueued for it.
        if input.message_body.is_empty() {
            return Err(crate::scaffolded::Scaffolded::missing_parameter(
                "MessageBody",
            ));
        }

        // "A message can include only XML, JSON, and unformatted text. The following
        // Unicode characters are allowed ... If a message contains characters outside
        // the allowed set, Amazon SQS rejects the message and returns an
        // InvalidMessageContents error." Refused before the store is touched, so a
        // rejected body is never stored.
        if let Some(character) = sqs::invalid_body_character(&input.message_body) {
            return Err(SendMessageErrorModeled::InvalidMessageContents(
                InvalidMessageContents {
                    message: Some(sqs::invalid_body_character_message(character)),
                },
            )
            .into());
        }

        let store = sqs::service_state(&*self.engine).ok_or_else(|| {
            SendMessageErrorModeled::UnsupportedOperation(sqs::store_unavailable())
        })?;

        // A queue encrypted with a customer managed key is one Amazon SQS has to have
        // KMS generate a data key under, as this caller, before it can seal the message:
        // a caller the key does not permit — or a key KMS cannot use — is refused here,
        // so nothing is enqueued for a message that could not have been encrypted.
        let queue_key = sqs::encryption::authorize_queue_key(
            &*self.engine,
            ctx,
            &input.queue_url,
            sqs::encryption::GENERATE_DATA_KEY_ACTION,
        )
        .map_err(kms_refusal)?;

        // Whether this send is a client's own request or the NOTIFICATION FAN-OUT of a
        // published message, which Amazon SNS hands the queue as its own service principal on
        // behalf of the topic: the two are judged by different bounds (see the size rule
